// an approval when new code was pushed. This protocol fixes the binding:
//
//   1. The reviewer examines the branch at commit R (the code tip).
//   2. The loop records .agentic/reviews/<R>.json and commits it — that
//      commit must touch NOTHING outside .agentic/reviews/.
//   3. CI verifies: HEAD is a verdict-only commit (adds/modifies only, no
//      deletes — rename tricks decompose to a delete under --no-renames),
//      its first parent is R, the file pins R exactly, the reviewer is the
//      required cross-agent, the verdict is "approve" with zero blocking
//      findings, and quoted evidence is present.
//
// Any code pushed after the verdict makes HEAD a code commit again, so the
// check goes red until a fresh review is recorded. A stale approval cannot
// ride a new push into main.
//
// KNOWN LIMIT: without CI-side reviewer execution (CI_CODEX_REVIEW +
// OPENAI_API_KEY), the reviewer identity is attested by the recording agent —
// the protocol proves WHAT was approved and WHEN it went stale, not WHO
// approved it. CI runs the copy of this script from origin/main, so a PR
// cannot weaken or delete the verifier it is judged by.
//
// Usage:
//   node scripts/verify-review-verdict.mjs [--ci]        verify HEAD
//   node scripts/verify-review-verdict.mjs --record \
//     --reviewer codex --evidence-file <path>            record for HEAD
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REVIEWS_DIR = '.agentic/reviews';
const MIN_EVIDENCE_LENGTH = 40;

function git(args, options = {}) {
  return execFileSync('git', args, { encoding: 'utf8', ...options }).trim();
}

export function requiredReviewers(branch) {
  if (branch.startsWith('claude/')) return ['codex'];
  if (branch.startsWith('codex/')) return ['claude'];
  if (branch.startsWith('copilot/')) return ['codex', 'claude'];
  return null; // not an agent branch — no verdict required
}

// headEntries: [{ status, file }] from a --no-renames name-status diff of the
// HEAD commit. Statuses other than A/M (deletes, type changes) can never be
// part of a legitimate verdict commit; with rename detection disabled a
// "rename a code file onto the verdict path" trick decomposes into D + A and
// the D is rejected here.
export function validateVerdict({ branch, headEntries, headParent, verdictJson }) {
  const reviewers = requiredReviewers(branch);
  if (reviewers === null) return { ok: true, reason: 'not an agent branch; verdict not required' };

  const failures = [];
  const expectedFile = `${REVIEWS_DIR}/${headParent}.json`;

  const offending = headEntries.filter(
    (e) => !e.file.startsWith(`${REVIEWS_DIR}/`) || (e.status !== 'A' && e.status !== 'M'),
  );
  if (headEntries.length === 0 || offending.length > 0) {
    failures.push(
      'HEAD is not a verdict-only commit. The tip of an agent branch must be a commit '
        + `that only adds or modifies files under ${REVIEWS_DIR}/, recording the cross-agent review of its parent. `
        + (offending.length > 0 ? `Offending entries: ${offending.map((e) => [e.status, e.file].join(' ')).join(', ')}. ` : '')
        + 'Run the review, then: node scripts/verify-review-verdict.mjs --record --reviewer <agent> --evidence-file <transcript>',
    );
    return { ok: false, failures };
  }
  if (!headEntries.some((e) => e.file === expectedFile)) {
    failures.push(
      `HEAD does not record a verdict for its parent: expected ${expectedFile}, got ${headEntries.map((e) => e.file).join(', ')}. `
        + 'The verdict must pin the exact commit the reviewer examined — re-run the review against the current tip.',
    );
    return { ok: false, failures };
  }

  let verdict;
  try {
    verdict = JSON.parse(verdictJson);
  } catch {
    failures.push(`${expectedFile} is not valid JSON.`);
    return { ok: false, failures };
  }

  if (verdict.reviewedSha !== headParent) {
    failures.push(`Verdict pins ${verdict.reviewedSha}, but the reviewed commit is ${headParent}.`);
  }
  if (!reviewers.includes(String(verdict.reviewer || '').toLowerCase())) {
    failures.push(
      `Reviewer "${verdict.reviewer}" is not a valid cross-agent for ${branch.split('/')[0]}/* — `
        + `required: ${reviewers.join(' or ')}. Self-review does not count.`,
    );
  }
  if (verdict.verdict !== 'approve') {
    failures.push(`Verdict is "${verdict.verdict}", not "approve".`);
  }
  if (verdict.blockingFindings !== 0) {
    failures.push(`blockingFindings is ${verdict.blockingFindings}; a verdict may only be recorded at zero.`);
  }
  if (typeof verdict.evidence !== 'string' || verdict.evidence.trim().length < MIN_EVIDENCE_LENGTH) {
    failures.push(
      `evidence must quote the reviewer's actual concluding output (>= ${MIN_EVIDENCE_LENGTH} chars), `
        + 'never a paraphrase.',
    );
  }
  return failures.length > 0 ? { ok: false, failures } : { ok: true, reason: `verdict by ${verdict.reviewer} for ${headParent}` };
}

function headState(cwd) {
  const headSha = git(['rev-parse', 'HEAD'], { cwd });
  let headParent = '';
  try {
    headParent = git(['rev-parse', 'HEAD^'], { cwd });
  } catch { /* root commit — headEntries below still lists its files */ }
  const raw = headParent
    ? git(['diff-tree', '--no-renames', '--name-status', '-r', headParent, headSha], { cwd })
    : git(['diff-tree', '--no-renames', '--name-status', '-r', '--root', headSha], { cwd })
        .split('\n').slice(1).join('\n'); // --root prefixes the commit hash line
  const headEntries = raw.split('\n').filter(Boolean).map((line) => {
    const [status, ...rest] = line.split('\t');
    return { status: status.trim(), file: rest.join('\t') };
  });
  return { headSha, headParent, headEntries };
}

function currentBranch(cwd) {
  return process.env.GITHUB_HEAD_REF || git(['rev-parse', '--abbrev-ref', 'HEAD'], { cwd });
}

export function verify(cwd = process.cwd()) {
  const branch = currentBranch(cwd);
  const { headParent, headEntries } = headState(cwd);
  let verdictJson = '';
  if (headParent) {
    try {
      verdictJson = git(['show', `HEAD:${REVIEWS_DIR}/${headParent}.json`], { cwd });
    } catch { /* validated below via headEntries */ }
  }
  return { branch, ...validateVerdict({ branch, headEntries, headParent, verdictJson }) };
}

function record(cwd, { reviewer, evidenceFile }) {
  const branch = currentBranch(cwd);
  const reviewers = requiredReviewers(branch);
  if (reviewers === null) throw new Error(`${branch} is not an agent branch; nothing to record.`);
  if (!reviewers.includes(reviewer)) {
    throw new Error(`Reviewer "${reviewer}" is not a valid cross-agent for this branch (required: ${reviewers.join(' or ')}).`);
  }
  // Untracked files (evidence transcripts, worktree node_modules symlinks) do
  // not change the committed state the verdict pins; tracked modifications do.
  if (git(['status', '--porcelain', '--untracked-files=no'], { cwd })) {
    throw new Error('Tracked files have uncommitted changes; a verdict must pin an exact committed state.');
  }
  const { headSha, headEntries } = headState(cwd);
  if (headEntries.length > 0 && headEntries.every((e) => e.file.startsWith(`${REVIEWS_DIR}/`))) {
    throw new Error('HEAD is already a verdict commit; do not stack verdicts. Push code first, then re-review.');
  }
  const evidence = readFileSync(evidenceFile, 'utf8').trim();
  if (evidence.length < MIN_EVIDENCE_LENGTH) {
    throw new Error(`Evidence file is too short to be a real reviewer conclusion (< ${MIN_EVIDENCE_LENGTH} chars).`);
  }
  const file = path.join(cwd, REVIEWS_DIR, `${headSha}.json`);
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, `${JSON.stringify({
    reviewedSha: headSha,
    reviewer,
    verdict: 'approve',
    blockingFindings: 0,
    reviewedAt: new Date().toISOString(),
    evidence,
  }, null, 2)}\n`);
  git(['add', `${REVIEWS_DIR}/${headSha}.json`], { cwd });
  git(['commit', '--no-verify', '-m', `agentic: record ${reviewer} review verdict for ${headSha.slice(0, 8)}`], { cwd });
  return verify(cwd);
}

function main() {
  const args = process.argv.slice(2);
  const get = (flag) => {
    const i = args.indexOf(flag);
    return i === -1 ? undefined : args[i + 1];
  };

  if (args.includes('--record')) {
    const reviewer = get('--reviewer');
    const evidenceFile = get('--evidence-file');
    if (!reviewer || !evidenceFile) {
      console.error('Usage: verify-review-verdict.mjs --record --reviewer <codex|claude> --evidence-file <path>');
      process.exit(2);
    }
    const result = record(process.cwd(), { reviewer: reviewer.toLowerCase(), evidenceFile });
    if (!result.ok) {
      console.error('[review-verdict] Recorded verdict failed self-verification:');
      for (const f of result.failures) console.error(`  - ${f}`);
      process.exit(1);
    }
    console.log(`[review-verdict] Recorded and verified: ${result.reason}`);
    return;
  }

  const result = verify(process.cwd());
  if (result.ok) {
    console.log(`[review-verdict] PASS (${result.branch}): ${result.reason}`);
    return;
  }
  console.error(`[review-verdict] FAIL (${result.branch}):`);
  for (const f of result.failures) console.error(`  - ${f}`);
  process.exit(1);
}

// Resolved-path equality, not basename. This module is imported by
// cross-agent-check.mjs for requiredReviewers(); under the basename guard an
// entrypoint merely NAMED verify-review-verdict.mjs made that import run the
// gate CLI and exit 1.
const isDirectRun = process.argv[1]
  && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectRun) main();
#!/usr/bin/env node
import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { requiredReviewers } from './verify-review-verdict.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = new Set(process.argv.slice(2));

function run(command, commandArgs, options = {}) {
  try {
    return execFileSync(command, commandArgs, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      ...options,
    }).trim();
  } catch {
    return '';
  }
}

function hasCommand(command) {
  return Boolean(run('sh', ['-c', `command -v ${command}`]));
}

function currentBranch() {
  return process.env.GITHUB_HEAD_REF || run('git', ['rev-parse', '--abbrev-ref', 'HEAD']) || '';
}

function baseRef() {
  const candidates = [
    process.env.GITHUB_BASE_REF ? `origin/${process.env.GITHUB_BASE_REF}` : '',
    'origin/main',
    'macos/main',
    'main',
    'HEAD~1',
  ].filter(Boolean);

  for (const candidate of candidates) {
    if (run('git', ['rev-parse', '--verify', candidate])) return candidate;
  }
  return 'HEAD~1';
}

function changedFiles() {
  const base = baseRef();
  const mergeBase = run('git', ['merge-base', base, 'HEAD']) || base;
  const outputs = [
    run('git', ['diff', '--name-only', `${mergeBase}...HEAD`]),
    run('git', ['diff', '--name-only', '--cached']),
    run('git', ['diff', '--name-only']),
    run('git', ['ls-files', '--others', '--exclude-standard']),
  ];
  return [...new Set(outputs
    .join('\n')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean))].sort();
}

function changedAreas(files) {
  const rules = [
    ['sidecar/api', (file) => file.startsWith('src-tauri/sidecar/') || file.startsWith('api/')],
    ['tauri', (file) => file.startsWith('src-tauri/src/')],
    ['ui', (file) => file.startsWith('src/components/')],
    ['services', (file) => file.startsWith('src/services/')],
    ['config', (file) => file.startsWith('src/config/')],
    ['ci', (file) => file.startsWith('.github/')],
    ['tooling', (file) => file.startsWith('scripts/')],
    ['tests', (file) => file.startsWith('tests/') || file.startsWith('e2e/') || file.includes('.test.')],
    ['docs', (file) => file.endsWith('.md')],
  ];
  const areas = new Set();
  for (const file of files) {
    for (const [area, matches] of rules) {
      if (matches(file)) areas.add(area);
    }
  }
  return [...areas].sort();
}

// Branch → reviewer is owned by verify-review-verdict.mjs (it is the script that
// ENFORCES the mapping); duplicating it here would let the advice drift from the gate.
const titleCase = (slug) => slug.charAt(0).toUpperCase() + slug.slice(1);

export function expectedReviewer(branch) {
  const reviewers = requiredReviewers(branch);
  return reviewers === null ? 'another agent' : reviewers.map((r) => titleCase(r)).join(' or ');
}

// The --reviewer flag takes one slug. A copilot/* branch accepts either agent, so
// the operator must choose; a non-agent branch records no verdict at all.
export function verdictAdvice(branch) {
  const reviewers = requiredReviewers(branch);
  if (reviewers === null) return null;
  const slug = reviewers.length === 1 ? reviewers[0] : `<${reviewers.join('|')}>`;
  return [
    'After the second review, record the verdict as a SHA-pinned commit (a PR-body',
    'marker no longer satisfies the gate — see .github/workflows/cross-agent-review.yml):',
    '```',
    `node scripts/verify-review-verdict.mjs --record --reviewer ${slug} --evidence-file <review-output>`,
    '```',
    'That flag both writes .agentic/reviews/<sha>.json and commits it — do not commit again.',
    'It pins the reviewed SHA, so record it LAST: any later code commit invalidates the',
    'verdict and the gate stays red until a fresh review is recorded.',
  ];
}

function requiredFilesPresent() {
  return [
    '.github/workflows/cross-agent-review.yml',
    'scripts/cross-agent-check.mjs',
    'scripts/verify-review-verdict.mjs',
  ].filter((file) => !existsSync(path.resolve(root, file)));
}

function printLocalReport({ branch, files, areas, reviewer }) {
  console.log('Crystal Ball cross-agent check');
  console.log(`Branch: ${branch || '(unknown)'}`);
  console.log(`Changed files: ${files.length}`);
  console.log(`Changed areas: ${areas.length ? areas.join(', ') : 'none detected'}`);
  console.log(`Required reviewer: ${reviewer}`);
  console.log('');

  console.log('Available local review tools:');
  console.log(`- Claude CLI: ${hasCommand('claude') ? 'available' : 'missing'}`);
  console.log(`- Codex CLI: ${hasCommand('codex') ? 'available' : 'missing'}`);
  console.log(`- GitHub CLI: ${hasCommand('gh') ? 'available' : 'missing'}`);
  console.log(`- Qodo CLI: ${hasCommand('qodo') ? 'available' : 'missing (optional)'}`);
  console.log(`- CodeRabbit CLI: ${hasCommand('coderabbit') ? 'available' : 'missing (optional)'}`);
  console.log('');

  console.log('Second-agent review prompt:');
  console.log('```');
  console.log(`Review the current Crystal Ball branch ${branch || '(current branch)'} as an independent reviewer.`);
  console.log(`Focus on changed files since ${baseRef()}. Prioritize bugs, regressions, security risks, missing tests, and CI/release hazards.`);
  console.log(`Changed areas: ${areas.length ? areas.join(', ') : 'none detected'}.`);
  if (areas.includes('sidecar/api')) {
    console.log('Also apply the sidecar-reviewer checklist for CORS proxy routes, timeouts, JSON errors, API keys, and sidecar tests.');
  }
  console.log('Return findings first with file/line references, then test gaps and residual risk.');
  console.log('```');
  console.log('');

  const advice = verdictAdvice(branch);
  if (advice) {
    for (const line of advice) console.log(line);
  } else {
    console.log('Not an agent branch: no cross-agent verdict is required or recordable.');
  }
}

function collectFailures() {
  const failures = [];
  const missing = requiredFilesPresent();
  if (missing.length > 0) {
    failures.push(`Missing cross-agent workflow file(s): ${missing.join(', ')}`);
  }
  return failures;
}

function reportFailures(failures, { ci }) {
  if (ci && !args.has('--verbose')) {
    for (const failure of failures) console.error(`[cross-check] ${failure}`);
    return;
  }
  console.log('');
  console.log('Failures:');
  for (const failure of failures) console.log(`- ${failure}`);
}

function main() {
  const branch = currentBranch();
  const files = changedFiles();
  const areas = changedAreas(files);
  const reviewer = expectedReviewer(branch);
  const ci = args.has('--ci') || Boolean(process.env.CI);
  const failures = collectFailures();

  if (!ci || args.has('--verbose')) {
    printLocalReport({ branch, files, areas, reviewer });
    if (failures.length > 0) reportFailures(failures, { ci });
  }

  if (failures.length > 0) {
    if (ci && !args.has('--verbose')) reportFailures(failures, { ci });
    process.exit(1);
  }

  // The review verdict itself is enforced by verify-review-verdict.mjs / ci-codex-review.mjs
  // from origin/main; this script only advises and asserts the gate files exist.
  if (ci) console.log('[cross-check] Cross-agent gate files present.');
}

// Resolved-path equality, not basename: a different entrypoint that happens to be
// named cross-agent-check.mjs must not trigger the CLI on import.
const isDirectRun = process.argv[1]
  && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectRun) main();
name: Cross-agent review gate

# Machine-verifiable cross-agent review. The old gate looked for a free-text
# marker in the PR body — self-attestable, never tied to a commit, and #1601
# merged mid-review because a new push did not invalidate the "approval".
#
# Two paths, strongest available wins:
#   1. CI_CODEX_REVIEW repo variable 'on' + OPENAI_API_KEY secret, same-repo
#      AGENT branches only -> Codex reviews the diff IN CI and the verdict
#      comes from the reviewer itself (no self-attestation possible).
#   2. Otherwise -> verify the SHA-pinned verdict commit recorded by the local
#      review loop. Any code push after the verdict turns the check red until
#      a fresh review is recorded.
#
# Both verifier scripts are executed FROM origin/main, never from the PR head:
# a PR must not be able to weaken or delete the gate that judges it.
on:
  pull_request:
    types: [opened, synchronize, reopened, ready_for_review]
    branches:
      - main
  # No PR context inside the merge queue; the gate was already enforced when
  # the PR entered the queue, so report success.
  merge_group:

permissions:
  contents: read

jobs:
  cross-agent-review:
    runs-on: ubuntu-latest
    timeout-minutes: 20
    steps:
      - name: Skip in merge queue
        if: github.event_name == 'merge_group'
        run: echo "Cross-agent gate is enforced at PR time; nothing to re-verify inside the merge queue."

      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        if: github.event_name == 'pull_request'
        with:
          # The default pull_request checkout is the SYNTHETIC MERGE commit;
          # the verdict protocol must examine the actual branch tip.
          ref: ${{ github.event.pull_request.head.sha }}
          fetch-depth: 0

      - name: Review gate
        if: github.event_name == 'pull_request'
        env:
          # GITHUB_HEAD_REF is runner-provided; branch names are consumed only
          # by case-pattern matching and the Node scripts, never interpolated.
          CI_CODEX_MODE: ${{ vars.CI_CODEX_REVIEW }}
          IS_SAME_REPO: ${{ github.event.pull_request.head.repo.full_name == github.repository }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
        run: |
          case "$GITHUB_HEAD_REF" in
            claude/*|codex/*|copilot/*) AGENT_BRANCH=1 ;;
            *) AGENT_BRANCH=0 ;;
          esac
          if [ "$AGENT_BRANCH" = "0" ]; then
            echo "Not an agent branch; cross-agent review not required."
            exit 0
          fi
          git fetch origin main --quiet
          if [ "$CI_CODEX_MODE" = "on" ] && [ "$IS_SAME_REPO" = "true" ]; then
            if [ -z "$OPENAI_API_KEY" ]; then
              echo "CI_CODEX_REVIEW is on but the OPENAI_API_KEY secret is missing." >&2
              exit 1
            fi
            npm install -g @openai/codex@0.146.0 || npm install -g @openai/codex
            if git cat-file -e origin/main:scripts/ci-codex-review.mjs 2>/dev/null; then
              git show origin/main:scripts/ci-codex-review.mjs > "$RUNNER_TEMP/ci-codex-review.mjs"
            else
              cp scripts/ci-codex-review.mjs "$RUNNER_TEMP/ci-codex-review.mjs"
            fi
            node "$RUNNER_TEMP/ci-codex-review.mjs"
          else
            # Trusted copy: a PR that deletes or edits the verifier is still
            # judged by main's version. Only before the protocol first lands
            # on main does this fall back to passing.
            if git cat-file -e origin/main:scripts/verify-review-verdict.mjs 2>/dev/null; then
              git show origin/main:scripts/verify-review-verdict.mjs > "$RUNNER_TEMP/verify-review-verdict.mjs"
              node "$RUNNER_TEMP/verify-review-verdict.mjs" --ci
            else
              echo "verify-review-verdict.mjs not on origin/main yet (protocol rollout); passing."
            fi
          fi
